"""Release 1.72.575 AsbestosTools: one hunk on the LIVE inc/instruments.php (the require of inc/asbestos-tools.php). Generated by make_deploy575.py."""
RELS = ['inc/instruments.php']
HUNKS = {'inc/instruments.php': [("if ( file_exists( __DIR__ . '/rent-listings.php' ) ) { require_once __DIR__ . '/rent-listings.php'; }", "if ( file_exists( __DIR__ . '/rent-listings.php' ) ) { require_once __DIR__ . '/rent-listings.php'; }\n\n/* 1.72.575 (HAD-668): the asbestos page tools (asbcheck, asbcost, asbmap, asbwho); loaded only if present, so a rollback that removes it leaves this file working */\nif ( file_exists( __DIR__ . '/asbestos-tools.php' ) ) { require_once __DIR__ . '/asbestos-tools.php'; }", 1)]}


def apply(rel, txt):
    if rel not in HUNKS:
        raise SystemExit('ashira_575: no hunk on ' + rel)
    for old, new, n in HUNKS[rel]:
        if new in txt:
            raise SystemExit('ashira_575: the live %s already holds the new text' % rel)
        k = txt.count(old)
        if k != n:
            raise SystemExit('ashira_575: anchor x%d (want %d) in the live %s' % (k, n, rel))
        txt = txt.replace(old, new)
    return txt
